package de.lazytv.pro.catalog;
import java.util.*;import de.lazytv.pro.playlist.*;
public class StreamResolver { private final StalkerCatalogSource stalker; public StreamResolver(StalkerCatalogSource s){stalker=s;} public ResolvedStream resolve(Playlist p,StreamItem i)throws CatalogException{String url=i.streamUrl;Map<String,String> headers=new LinkedHashMap<>(),meta=new LinkedHashMap<>();if(p.getType()==PlaylistType.M3U_URL||p.getType()==PlaylistType.M3U_FILE){if(i instanceof M3uStreamItem)headers.putAll(((M3uStreamItem)i).requestHeaders);}if(p.getType()==PlaylistType.STALKER_PORTAL){StalkerCatalogSource.LinkResult x=stalker.resolve(p,i);url=x.url;headers.putAll(x.headers);}if(p.getType()==PlaylistType.XTREAM_CODES&&i.type==CatalogType.LIVE){try{meta.putAll(new XtreamCatalogSource().loadLiveEpg(p,i.id));}catch(Exception ignored){}}if(url==null||url.trim().isEmpty()||url.contains("://")&&url.startsWith("xtream-series://"))throw new CatalogException("Stream URL mungon");if(i instanceof Episode){Episode e=(Episode)i;meta.put("series_id",e.seriesId);meta.put("season",String.valueOf(e.seasonNumber));meta.put("episode",String.valueOf(e.episodeNumber));meta.put("duration",e.duration==null?"":e.duration);meta.put("container",e.extension==null?"":e.extension);meta.putAll(e.metadata);}return new ResolvedStream(url,i.type.name(),i.name,i.logo,i.tvgId,headers,meta);} }
